+export function ensurePlugFnDatabaseAdapter(
+  value: DbAdapter | PlugFnDatabaseStorageAdapter,
+  models?: Partial<PlugFnStorageModelMapping>
+): PlugFnDatabaseStorageAdapter {
+  if (isPlugFnDatabaseStorageAdapter(value)) {
+    return value;
+  }
